public class WarehouseInfo
{
    public static readonly WarehouseInfo[] All =
    [
        new("WH-001", "Warehouse A — East"),
        new("WH-002", "Warehouse B — West"),
        new("WH-003", "Warehouse C — Central"),
    ];

    public string Id { get; set; } = All[0].Id;
    public string Name { get; set; } = All[0].Name;

    public WarehouseInfo() { }

    public WarehouseInfo(string id, string name)
    {
        Id = id;
        Name = name;
    }
}

namespace sv_263a26f2f40d4c7abe453def355ef7a2.Services;

/// <summary>
/// Scoped service (one per circuit) that holds the latest low-stock alert count
/// and exposes an event so any subscribing component can re-render when data changes.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public int CurrentAlertCount { get; private set; }

    public event Action? OnChange;

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        _ = warehouseId; // would be used in a real query
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Called by the polling component after fetching new data.
    /// Stores the count and broadcasts to all subscribers.
    /// </summary>
    public void NotifyAlertCountChanged(int count)
    {
        CurrentAlertCount = count;
        OnChange?.Invoke();
    }
}

