@* Interactive dropdown for selecting the current warehouse.
   Rendered inside the static MainLayout but marked InteractiveServer
   so it can handle change events. Updates the CascadingValueSource
   which notifies all [CascadingParameter] subscribers. *@

@rendermode InteractiveServer
@using sv_263a26f2f40d4c7abe453def355ef7a2.Services
@inject CascadingValueSource<WarehouseInfo> WarehouseSource

<select class="form-select form-select-sm w-auto"
        value="@_selectedId"
        @onchange="OnWarehouseChanged">
    @foreach (var wh in WarehouseInfo.All)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private string _selectedId = WarehouseInfo.All[0].Id;

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        _selectedId = e.Value?.ToString() ?? WarehouseInfo.All[0].Id;
        var selected = WarehouseInfo.All.First(w => w.Id == _selectedId);
        await WarehouseSource.NotifyChangedAsync(
            new WarehouseInfo(selected.Id, selected.Name));
    }
}

@* Displays the current low-stock alert count as a Bootstrap badge.
   Subscribes to InventoryAlertService.OnChange so it re-renders
   whenever the polling component fetches new data. *@

@rendermode InteractiveServer
@using sv_263a26f2f40d4c7abe453def355ef7a2.Services
@inject InventoryAlertService Alerts
@implements IDisposable

@if (Alerts.CurrentAlertCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-2">@Alerts.CurrentAlertCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-2">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Event fires from a timer callback (background thread),
        // so wrap StateHasChanged in InvokeAsync.
        _handler = () => InvokeAsync(StateHasChanged);
        Alerts.OnChange += _handler;
    }

    public void Dispose()
    {
        Alerts.OnChange -= _handler;
    }
}

