@page "/dashboard"
@rendermode InteractiveServer
@using sv_263a26f2f40d4c7abe453def355ef7a2.Services
@inject InventoryAlertService Alerts
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-3" style="max-width: 30rem;">
    <div class="card-body">
        <h5 class="card-title">
            Current Warehouse: @Warehouse?.Name
        </h5>
        <p class="card-text text-muted">ID: @Warehouse?.Id</p>
    </div>
</div>

<div class="card mb-3" style="max-width: 30rem;">
    <div class="card-body d-flex align-items-center justify-content-between">
        <div>
            <h5 class="card-title mb-0">Low-Stock Alerts</h5>
            <small class="text-muted">Refreshes every 10 seconds</small>
        </div>
        @if (_alertCount > 0)
        {
            <span class="badge bg-danger fs-5">@_alertCount</span>
        }
        else
        {
            <span class="badge bg-success fs-5">0</span>
        }
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    private int _alertCount;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Subscribe to broadcasts from the scoped service so that if
        // another component triggers a refresh we also update.
        _handler = () => InvokeAsync(() =>
        {
            _alertCount = Alerts.CurrentAlertCount;
            StateHasChanged();
        });
        Alerts.OnChange += _handler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

            // Fetch immediately on load, then every 10 seconds.
            await PollAsync();
            _ = PollLoopAsync(_cts.Token);
        }
    }

    protected override async Task OnParametersSetAsync()
    {
        // Warehouse changed via cascading value — re-fetch immediately.
        await PollAsync();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await PollAsync();
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task PollAsync()
    {
        if (Warehouse is null) return;

        var count = await Alerts.GetLowStockCountAsync(Warehouse.Id);
        _alertCount = count;

        // Broadcast to all subscribers (sidebar badge, etc.)
        Alerts.NotifyAlertCountChanged(count);

        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        Alerts.OnChange -= _handler;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

